def sec_roles(d):
    d.h2("User Roles and Constraints")
    d.table([["Role", "Can do", "Cannot do"],
             ["Visitor (not signed in)", "See the landing page with the real model figures and one live example finding; register or sign in", "Run a review, open a repository or use any protected route"],
             ["Developer (signed in, including the demo account)", "Submit reviews, read and export results, delete reviews, index repositories and ask questions, use the Model Lab and re-train, change settings", "See other accounts' details; there are no further privilege levels"],
             ["External services", "GitHub (public API) supplies diffs and repositories; the Anthropic API rewrites explanations if the user enables it", "Receive code unless the user submits a GitHub link or enables the LLM option"]],
            "User roles", widths=[0.24, 0.46, 0.3], font=9.5)
    d.p("The system has one privilege level. The review history is not separated by account: every signed-in user can see every stored "
        "review, because the `reviews` table has no owner column. This suits a single-machine tool and is listed as a limitation and "
        f"as future work. For orientation: the stored {BEST} reaches F1 {f3(MODELS[BEST]['f1'])} on the generated test set, and the demo "
        f"pull request, which contains seven deliberately vulnerable functions, scores {DEMO['score']}.")
